/* Default configuration for lib_xuh.
 *
 * An application may override any option by defining it in an optional
 * xuh_conf.h header on its include path. Do not edit this file to configure an
 * application. */
#ifndef XUH_CONFIG_H_
#define XUH_CONFIG_H_

/* XCommon CMake defines this when the application supplies xuh_conf.h. */
#ifdef __xuh_conf_h_exists__
#include "xuh_conf.h"
#endif

/* Interface descriptors (alternate settings included) recorded per device. */
#ifndef XUH_MAX_INTERFACES
#define XUH_MAX_INTERFACES 4
#endif

/* Endpoint descriptors recorded per interface. */
#ifndef XUH_MAX_ENDPOINTS_PER_INTERFACE
#define XUH_MAX_ENDPOINTS_PER_INTERFACE 4
#endif

/* Non-control channel slots a host context can hold in each direction. */
#ifndef XUH_MAX_DATA_EPS
#define XUH_MAX_DATA_EPS 3
#endif

/* Largest configuration descriptor (wTotalLength) that can be enumerated.
 * XUH_Host_WaitForDevice() holds a buffer of this size on its stack. */
#ifndef XUH_CONFIG_DESC_MAX
#define XUH_CONFIG_DESC_MAX 512
#endif

/* Address given to the attached device. */
#ifndef XUH_DEVICE_ADDRESS
#define XUH_DEVICE_ADDRESS 3
#endif

/* 1: lib_xuh provides the FatFs disk I/O functions (disk_initialize() and so
 * on) for a mass storage device; see xuh_msc.h. The application must
 * then list lib_fatfs in its own dependencies: lib_xuh does not depend on it. */
#ifndef XUH_MSC_FATFS
#define XUH_MSC_FATFS 0
#endif

/* 1: print each mass storage command and its stages. */
#ifndef XUH_MSC_TRACE
#define XUH_MSC_TRACE 0
#endif

#endif
